script:
if (Test-Path 'HKCU:\Software\Foo') {
  Set-ItemProperty -Path 'HKCU:\Software\Foo' -Name Bar -Value 1
} else {
  New-Item -Path 'HKCU:\Software\Foo' | Out-Null
}

cmd.read:
$r = Get-NetFirewallRule -Name 'Rig-935f58b1' -ErrorAction SilentlyContinue
if ($r) { $r | Format-List -Property DisplayName, Enabled, Direction, Action, Profile; $r | Get-NetFirewallPortFilter | Format-List -Property Protocol, LocalPort, RemotePort; $r | Get-NetFirewallApplicationFilter | Format-List -Property Program }
else { 'Rig has not added this rule.' }

$r = Get-NetFirewallRule -Name 'Rig-a5a970a7' -ErrorAction SilentlyContinue
if ($r) { $r | Format-List -Property DisplayName, Enabled, Direction, Action, Profile; $r | Get-NetFirewallPortFilter | Format-List -Property Protocol, LocalPort, RemotePort; $r | Get-NetFirewallApplicationFilter | Format-List -Property Program }
else { 'Rig has not added this rule.' }

$r = Get-NetFirewallRule -Name 'Rig-83594996' -ErrorAction SilentlyContinue
if ($r) { $r | Format-List -Property DisplayName, Enabled, Direction, Action, Profile; $r | Get-NetFirewallPortFilter | Format-List -Property Protocol, LocalPort, RemotePort; $r | Get-NetFirewallApplicationFilter | Format-List -Property Program }
else { 'Rig has not added this rule.' }

cmd.run:
if (Get-CimInstance -ClassName Win32_ComputerSystem -Filter 'PartOfDomain = TRUE') { throw 'This PC is managed by a work or school (it is joined to a domain or enrolled in device management), so Rig won''t change its policies. Ask whoever manages it.' }
if (Get-ChildItem -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Enrollments' -ErrorAction SilentlyContinue | Get-ItemProperty | Where-Object -Property EnrollmentState -EQ -Value 1 | Where-Object -Property ProviderID -Match -Value '.') { throw 'This PC is managed by a work or school (it is joined to a domain or enrolled in device management), so Rig won''t change its policies. Ask whoever manages it.' }
if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\GameDVR')) { New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows\GameDVR' -Force | Out-Null }
Set-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\GameDVR' -Name 'AllowGameDVR' -Type DWord -Value 0

if (Get-CimInstance -ClassName Win32_ComputerSystem -Filter 'PartOfDomain = TRUE') { throw 'This PC is managed by a work or school (it is joined to a domain or enrolled in device management), so Rig won''t change its policies. Ask whoever manages it.' }
if (Get-ChildItem -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Enrollments' -ErrorAction SilentlyContinue | Get-ItemProperty | Where-Object -Property EnrollmentState -EQ -Value 1 | Where-Object -Property ProviderID -Match -Value '.') { throw 'This PC is managed by a work or school (it is joined to a domain or enrolled in device management), so Rig won''t change its policies. Ask whoever manages it.' }
if (-not (Test-Path -LiteralPath 'HKCU:\Software\Policies\Microsoft\Windows\Explorer')) { New-Item -Path 'HKCU:\Software\Policies\Microsoft\Windows\Explorer' -Force | Out-Null }
Set-ItemProperty -LiteralPath 'HKCU:\Software\Policies\Microsoft\Windows\Explorer' -Name 'DisableSearchBoxSuggestions' -Type DWord -Value 1

$d = Get-PnpDevice -InstanceId 'USB\VID_046D&PID_C52B\5&1A2B3C&0&2' -ErrorAction Stop
if ($d.ConfigManagerErrorCode -eq 22) { throw 'This device is already turned off.' }
if ($d.Class -in @('System', 'DiskDrive', 'SCSIAdapter', 'HDC', 'Volume', 'Processor', 'Computer')) { throw 'Windows needs this device to run, so Rig won''t turn it off.' }
if ($d.Class -in @('Display', 'Keyboard', 'Mouse') -and -not (Get-PnpDevice -Class $d.Class -PresentOnly -Status OK | Where-Object -Property InstanceId -NE -Value 'USB\VID_046D&PID_C52B\5&1A2B3C&0&2')) { throw 'It is the last working one of its kind on this PC, so Rig won''t turn it off.' }
Disable-PnpDevice -InstanceId 'USB\VID_046D&PID_C52B\5&1A2B3C&0&2' -Confirm:$false

$d = Get-PnpDevice -InstanceId 'ACPI\PNP0303\4&1' -ErrorAction Stop
if ($d.ConfigManagerErrorCode -eq 22) { throw 'This device is already turned off.' }
if ($d.Class -in @('System', 'DiskDrive', 'SCSIAdapter', 'HDC', 'Volume', 'Processor', 'Computer')) { throw 'Windows needs this device to run, so Rig won''t turn it off.' }
if ($d.Class -in @('Display', 'Keyboard', 'Mouse') -and -not (Get-PnpDevice -Class $d.Class -PresentOnly -Status OK | Where-Object -Property InstanceId -NE -Value 'ACPI\PNP0303\4&1')) { throw 'It is the last working one of its kind on this PC, so Rig won''t turn it off.' }
Disable-PnpDevice -InstanceId 'ACPI\PNP0303\4&1' -Confirm:$false

if (Get-AuthenticodeSignature -LiteralPath 'C:\Drivers\Realtek\rt640x64.cat' | Where-Object -Property Status -NE -Value 'Valid') { throw 'This driver''s catalog isn''t validly signed, so Rig won''t install it.' }
pnputil /add-driver 'C:\Drivers\Realtek\rt640x64.inf' /install
if ($LASTEXITCODE -notin @(0, 259, 3010)) { throw 'Windows didn''t add the driver. pnputil says why above.' }
